content:
:root {
    /* Color Palette */
    --bg-color: #f0f4f8;
    --primary-blue: #0056b3;
    --primary-blue-dark: #004494;
    --secondary-blue: #e6f0ff;
    --text-main: #333333;
    --text-muted: #666666;
    --white: #ffffff;

    /* Tiers */
    --gold: #FFD700;
    --silver: #C0C0C0;
    --bronze: #CD7F32;

    /* Styling */
    --border-radius: 12px;
    --shadow-sm: 0 2px 8px rgba(0,0,0,0.05);
    --shadow-md: 0 8px 24px rgba(0,0,0,0.1);
    --shadow-glass: 0 8px 32px rgba(31, 38, 135, 0.15);
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    font-family: 'Inter', sans-serif;
}

body {
    background-color: #e0e5ec;
    color: var(--text-main);
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

/* --- Device Mockup for Desktop --- */
.device-mockup {
    position: relative;
    width: 100%;
    height: 100vh;
    background: var(--bg-color);
}

@media (min-width: 768px) {
    .device-mockup {
        width: 375px;
        height: 812px; /* iPhone X dimensions roughly */
        border-radius: 40px;
        box-shadow: 0 0 0 10px #1f1f1f, 0 0 0 14px #3a3a3a, 0 20px 40px rgba(0,0,0,0.2);
        overflow: hidden;
        margin: 20px;
        background: #000;
    }
}

.device-screen {
    width: 100%;
    height: 100%;
    background: var(--bg-color);
    position: relative;
    overflow: hidden;
}

/* --- App Layout --- */
.app-container {
    width: 100%;
    height: 100%;
    position: relative;
}

.view {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: var(--bg-color);
    display: flex;
    flex-direction: column;
    transition: opacity 0.3s ease, transform 0.3s ease;
    z-index: 10;
}

.view.hidden {
    opacity: 0;
    pointer-events: none;
    transform: translateX(20px);
    z-index: 1;
}

.view.active-view {
    opacity: 1;
    transform: translateX(0);
    z-index: 10;
}

.flex-center {
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
    padding: 20px;
}

.flex-center-col {
    display: flex;
    align-items: center;
    flex-direction: column;
}

.scroll-content {
    flex: 1;
    overflow-y: auto;
    padding: 20px;
    padding-bottom: 40px;
}

/* --- Components --- */

.glass-card {
    background: rgba(255, 255, 255, 0.8);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.5);
    border-radius: var(--border-radius);
    padding: 30px;
    width: 100%;
    max-width: 320px;
    box-shadow: var(--shadow-glass);
    text-align: center;
}

.brand-logo {
    max-width: 180px;
    margin-bottom: 20px;
}

h1 { font-size: 24px; font-weight: 800; color: var(--primary-blue); }
h2 { font-size: 18px; font-weight: 600; color: var(--text-main); margin-bottom: 10px; }
.subtitle { font-size: 14px; color: var(--text-muted); margin-bottom: 20px; }

/* Forms */
.input-group {
    margin-bottom: 15px;
    text-align: left;
}
.input-group label {
    display: block;
    font-size: 12px;
    font-weight: 600;
    color: var(--text-muted);
    margin-bottom: 5px;
}
.input-group input, .input-group select {
    width: 100%;
    padding: 12px;
    border: 1px solid #ccc;
    border-radius: 8px;
    font-size: 14px;
    outline: none;
    transition: border-color 0.2s;
    background: var(--white);
}
.input-group input:focus, .input-group select:focus {
    border-color: var(--primary-blue);
}

.btn {
    width: 100%;
    padding: 14px;
    border: none;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.1s, background-color 0.2s;
}
.btn:active { transform: scale(0.98); }

.btn-primary {
    background-color: var(--primary-blue);
    color: var(--white);
    box-shadow: 0 4px 12px rgba(0, 86, 179, 0.3);
}
.btn-primary:hover { background-color: var(--primary-blue-dark); }

.btn-secondary {
    background-color: var(--secondary-blue);
    color: var(--primary-blue);
}

.btn-icon {
    background: transparent;
    border: none;
    font-size: 24px;
    color: var(--primary-blue);
    cursor: pointer;
    padding: 5px;
}

.admin-link {
    font-size: 12px;
    color: var(--text-muted);
    margin-top: 15px;
    text-decoration: underline;
    cursor: pointer;
}

/* Header */
.app-header {
    background: var(--white);
    padding: 15px 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: var(--shadow-sm);
    z-index: 20;
}
.app-header.no-bg {
    background: transparent;
    box-shadow: none;
}
.font-bold { font-weight: 600; }
.text-small { font-size: 12px; color: var(--text-muted); }

.points-badge {
    background: var(--primary-blue);
    color: var(--white);
    padding: 6px 12px;
    border-radius: 20px;
    font-weight: 800;
    display: flex;
    align-items: center;
    gap: 5px;
    box-shadow: 0 2px 8px rgba(0, 86, 179, 0.3);
}
.points-badge i { color: var(--gold); }

/* Sponsor List */
.list-container {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.sponsor-card, .challenge-card {
    background: var(--white);
    border-radius: var(--border-radius);
    padding: 15px;
    display: flex;
    align-items: center;
    gap: 15px;
    box-shadow: var(--shadow-sm);
    cursor: pointer;
    transition: transform 0.2s;
}
.sponsor-card:active, .challenge-card:active { transform: scale(0.98); }
.sponsor-card.completed { opacity: 0.6; pointer-events: none; }

.sponsor-logo {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    object-fit: cover;
    background: #f0f0f0;
}

.sponsor-info, .challenge-info { flex: 1; }
.sponsor-info h3, .challenge-info h3 { font-size: 16px; margin-bottom: 2px; }
.sponsor-info p, .challenge-info p { font-size: 12px; color: var(--text-muted); }

.tier-badge {
    padding: 4px 8px;
    border-radius: 12px;
    font-size: 10px;
    font-weight: 800;
    text-transform: uppercase;
}
.tier-gold { background: rgba(255, 215, 0, 0.2); color: #B8860B; }
.tier-silver { background: rgba(192, 192, 192, 0.3); color: #696969; }
.tier-bronze { background: rgba(205, 127, 50, 0.2); color: #8B4513; }

.challenge-icon {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    background: var(--secondary-blue);
    color: var(--primary-blue);
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 20px;
}
.challenge-points {
    font-weight: 800;
    color: #28a745;
    font-size: 14px;
}

.mt-4 { margin-top: 24px; }

/* Quiz */
.sponsor-logo-large {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    margin-bottom: 20px;
    box-shadow: var(--shadow-md);
    background: #fff;
}
.quiz-card {
    background: var(--white);
    padding: 20px;
    border-radius: var(--border-radius);
    width: 100%;
    box-shadow: var(--shadow-md);
}
.quiz-question {
    font-size: 16px;
    font-weight: 600;
    margin-bottom: 20px;
    text-align: center;
}
.quiz-options {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.quiz-option {
    padding: 12px 15px;
    border: 1px solid #ddd;
    border-radius: 8px;
    background: var(--white);
    font-size: 14px;
    cursor: pointer;
    transition: all 0.2s;
    text-align: left;
}
.quiz-option:hover { border-color: var(--primary-blue); background: var(--secondary-blue); }
.quiz-option.correct { background: #d4edda; border-color: #28a745; color: #155724; }
.quiz-option.wrong { background: #f8d7da; border-color: #dc3545; color: #721c24; }

.feedback-msg {
    margin-top: 15px;
    text-align: center;
    font-weight: 600;
    font-size: 14px;
    padding: 10px;
    border-radius: 8px;
}
.feedback-msg.success { background: #d4edda; color: #155724; }
.feedback-msg.error { background: #f8d7da; color: #721c24; }

/* Loader */
.loader {
    border: 4px solid var(--secondary-blue);
    border-top: 4px solid var(--primary-blue);
    border-radius: 50%;
    width: 40px;
    height: 40px;
    animation: spin 1s linear infinite;
    margin-bottom: 15px;
}
@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }

/* Admin Tabs */
.admin-tabs {
    display: flex;
    background: var(--white);
    border-bottom: 1px solid #ddd;
}
.tab-btn {
    flex: 1;
    padding: 12px;
    border: none;
    background: transparent;
    font-weight: 600;
    color: var(--text-muted);
    cursor: pointer;
    border-bottom: 2px solid transparent;
}
.tab-btn.active {
    color: var(--primary-blue);
    border-bottom: 2px solid var(--primary-blue);
}

.leaderboard-item {
    display: flex;
    justify-content: space-between;
    padding: 12px;
    background: var(--white);
    border-radius: 8px;
    margin-bottom: 8px;
    box-shadow: var(--shadow-sm);
}
.lb-rank { font-weight: 800; color: var(--primary-blue); width: 30px; }
.lb-info { flex: 1; }
.lb-name { font-weight: 600; font-size: 14px;}
.lb-company { font-size: 11px; color: var(--text-muted); }
.lb-points { font-weight: 800; color: var(--gold); }

/* Survey styles */
.survey-section {
    margin-bottom: 20px;
    width: 100%;
}
.stars {
    display: flex;
    gap: 10px;
    font-size: 24px;
    color: #ccc;
    cursor: pointer;
}
.stars i.active { color: var(--gold); }
textarea {
    width: 100%;
    height: 80px;
    padding: 10px;
    border-radius: 8px;
    border: 1px solid #ccc;
    resize: none;
}

/* Modern UI components for Registration */
.modern-input-group {
    margin-bottom: 15px;
}
.modern-input {
    width: 100%;
    padding: 20px;
    border: none;
    border-radius: 16px;
    background-color: #ffffff;
    font-size: 14px;
    font-weight: 800;
    color: #0b1a30;
    outline: none;
    box-shadow: 0 4px 15px rgba(0,0,0,0.02);
}
.modern-input::placeholder {
    color: #0b1a30;
}
.btn-pill {
    width: 100%;
    padding: 18px;
    border: none;
    border-radius: 30px;
    background-color: #8daafc;
    color: white;
    font-size: 16px;
    font-weight: 800;
    cursor: pointer;
    box-shadow: 0 4px 15px rgba(141, 170, 252, 0.4);
    display: flex;
    justify-content: center;
    align-items: center;
    transition: transform 0.1s, opacity 0.2s;
}
.btn-pill:active {
    transform: scale(0.98);
}
.btn-text-only {
    width: 100%;
    padding: 15px;
    background: transparent;
    border: none;
    color: #4a5c75;
    font-size: 12px;
    font-weight: 800;
    margin-top: 10px;
    cursor: pointer;
}
.event-card {
    background-color: #ffffff;
    border: 2px solid transparent;
    border-radius: 20px;
    padding: 20px 25px;
    margin-bottom: 15px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    box-shadow: 0 4px 15px rgba(0,0,0,0.02);
    transition: all 0.2s;
}
.event-card.active-card {
    border-color: #1a4ef5;
}
.event-card-info h3 {
    font-size: 16px;
    font-weight: 800;
    color: #0b1a30;
    margin-bottom: 4px;
}
.event-card-info p {
    font-size: 10px;
    font-weight: 800;
    color: #8fa0ba;
    text-transform: uppercase;
}
.event-card i {
    color: #8fa0ba;
    font-size: 24px;
}
.event-card.active-card i {
    color: #1a4ef5;
}

const app = {
    currentUser: null,
    currentEventId: null,
    sponsors: [],
    activities: [],

    init() {
        if (window.location.hash === '#admin' || window.location.search.includes('admin=true')) {
            this.showView('view-admin');
        } else {
            this.loadEvents();
        }

        document.getElementById('login-form').addEventListener('submit', (e) => this.handleLogin(e));
    },

    showView(viewId, ...args) {
        document.querySelectorAll('.view').forEach(el => {
            el.classList.remove('active-view');
            setTimeout(() => el.classList.add('hidden'), 300);
        });

        const target = document.getElementById(viewId);
        target.classList.remove('hidden');
        setTimeout(() => target.classList.add('active-view'), 50);

        if (viewId === 'view-extra' && args.length > 0) {
            this.renderExtraChallenge(args[0]);
        }
    },

    async loadEvents() {
        try {
            const events = await dbAPI.getEvents();
            if (events && Array.isArray(events) && events.length > 0) {
                const list = document.getElementById('events-list');
                list.innerHTML = '';
                events.forEach(ev => {
                    const card = document.createElement('div');
                    card.className = 'event-card';
                    const location = ev.location || ev.name.split(' - ')[1] || 'ALAS';
                    card.innerHTML = `
                        <div class="event-card-info">
                            <h3>${ev.name.split(' - ')[0]}</h3>
                            <p>${location}</p>
                        </div>
                        <i class="ph ph-map-pin"></i>
                    `;
                    card.onclick = () => {
                        this.currentEventId = ev.id;
                        document.getElementById('register-event-name').textContent = 'WORKSHOP ' + location.toUpperCase();
                        this.showView('view-register');
                    };
                    list.appendChild(card);
                });
            } else {
                console.warn("No events loaded or events is not an array");
                document.getElementById('events-list').innerHTML = '<p style="color:#d9534f; text-align:center; padding:20px; font-weight:bold; font-size:12px;">No se encontraron eventos o están siendo bloqueados por tu navegador (revisa si tienes AdBlocker activado).</p>';
            }
        } catch (e) {
            console.error("Failed to load events", e);
            document.getElementById('events-list').innerHTML = '<p style="color:#d9534f; text-align:center; padding:20px; font-weight:bold; font-size:12px;">Error en JS: ' + e.message + '</p>';
        } finally {
            this.showView('view-events');
        }
    },

    async handleLogin(e) {
        e.preventDefault();
        const eventId = this.currentEventId;
        const name = document.getElementById('user-name').value;
        const company = document.getElementById('user-company').value;
        const email = document.getElementById('user-email').value;

        if (!eventId || !name || !email) return;

        const btn = document.getElementById('btn-submit-register');
        const origText = btn.innerHTML;
        btn.innerHTML = '<i class="ph ph-spinner ph-spin" style="font-size: 24px;"></i>';

        try {
            this.currentUser = await dbAPI.loginUser(eventId, name, company, email);
            await this.loadDashboardData();
            this.showView('view-dashboard');
        } catch (e) {
            console.error("Login failed", e);
            alert("Error al iniciar sesión.");
            this.showView('view-register');
        } finally {
            btn.innerHTML = origText;
        }
    },

    async loadDashboardData() {
        this.sponsors = await dbAPI.getSponsors(this.currentEventId);
        this.activities = await dbAPI.getUserActivities(this.currentUser.id);

        // Update user info
        document.getElementById('dash-name').textContent = this.currentUser.name;

        // Use the selected option's text for event name
        const selectEl = document.getElementById('event-select');
        document.getElementById('dash-event').textContent = selectEl.options[selectEl.selectedIndex].text;

        // Calculate total points from activities or use user total
        let points = this.currentUser.total_points || 0;
        document.getElementById('dash-points').textContent = points;

        this.renderSponsors();
    },

    renderSponsors() {
        const container = document.getElementById('sponsors-list');
        container.innerHTML = '';

        // Sort: Gold -> Silver -> Bronze
        const tierOrder = { 'gold': 1, 'silver': 2, 'bronze': 3 };
        const sorted = [...this.sponsors].sort((a, b) => tierOrder[a.tier] - tierOrder[b.tier]);

        sorted.forEach(s => {
            const isCompleted = this.activities.some(act => act.sponsorId === s.id && act.type === 'sponsor_quiz');

            const card = document.createElement('div');
            card.className = `sponsor-card ${isCompleted ? 'completed' : ''}`;
            if (!isCompleted) {
                card.onclick = () => this.openQuiz(s);
            }

            let tierClass = `tier-${s.tier}`;
            let tierName = s.tier === 'gold' ? 'ORO' : (s.tier === 'silver' ? 'PLATA' : 'BRONCE');

            card.innerHTML = `
                <img src="${s.logo}" class="sponsor-logo" alt="${s.name}" onerror="this.src='https://via.placeholder.com/50'">
                <div class="sponsor-info">
                    <h3>${s.name}</h3>
                    <p><span class="tier-badge ${tierClass}">${tierName}</span> • ${s.points} pts</p>
                </div>
                <div>
                    ${isCompleted ? '<i class="ph ph-check-circle" style="color: #28a745; font-size: 24px;"></i>' : '<i class="ph ph-caret-right" style="color: var(--primary-blue);"></i>'}
                </div>
            `;
            container.appendChild(card);
        });
    },

    openQuiz(sponsor) {
        document.getElementById('quiz-sponsor-name').textContent = sponsor.name;
        document.getElementById('quiz-sponsor-logo').src = sponsor.logo;
        document.getElementById('quiz-question').textContent = sponsor.question;

        const optionsContainer = document.getElementById('quiz-options');
        optionsContainer.innerHTML = '';

        const feedback = document.getElementById('quiz-feedback');
        feedback.className = 'feedback-msg hidden';

        sponsor.options.forEach((optText, index) => {
            const btn = document.createElement('button');
            btn.className = 'quiz-option';
            btn.textContent = optText;
            btn.onclick = () => this.submitQuiz(sponsor, index, btn);
            optionsContainer.appendChild(btn);
        });

        this.showView('view-sponsor');
    },

    async submitQuiz(sponsor, selectedIndex, btnElement) {
        // Disable all buttons
        const btns = document.querySelectorAll('.quiz-option');
        btns.forEach(b => b.disabled = true);

        const feedback = document.getElementById('quiz-feedback');
        feedback.classList.remove('hidden');

        if (selectedIndex === sponsor.correct) {
            btnElement.classList.add('correct');
            feedback.textContent = `¡Correcto! Has ganado ${sponsor.points} puntos.`;
            feedback.className = 'feedback-msg success';

            await dbAPI.registerActivity(this.currentUser.id, 'sponsor_quiz', sponsor.points, sponsor.id);
            this.currentUser.total_points += sponsor.points;

            setTimeout(() => {
                this.loadDashboardData();
                this.showView('view-dashboard');
            }, 2000);
        } else {
            btnElement.classList.add('wrong');
            // Show correct answer
            btns[sponsor.correct].classList.add('correct');
            feedback.textContent = 'Respuesta incorrecta. ¡Sigue intentando con otros patrocinadores!';
            feedback.className = 'feedback-msg error';

            // Still register activity with 0 points to mark as completed (or let them retry based on rules. Rules say "no permite generar oportunidad, queda ligada al usuario")
            await dbAPI.registerActivity(this.currentUser.id, 'sponsor_quiz', 0, sponsor.id);

            setTimeout(() => {
                this.loadDashboardData();
                this.showView('view-dashboard');
            }, 3000);
        }
    },

    renderExtraChallenge(type) {
        const titleEl = document.getElementById('extra-title');
        const contentEl = document.getElementById('extra-content');
        contentEl.innerHTML = '';

        // Check if already completed
        const isCompleted = this.activities.some(act => act.type === type);

        if (isCompleted) {
            titleEl.textContent = "Reto Completado";
            contentEl.innerHTML = `
                <i class="ph ph-check-circle" style="font-size: 80px; color: #28a745; margin-bottom: 20px;"></i>
                <h3 style="text-align: center;">Ya completaste este reto.</h3>
                <button class="btn btn-primary mt-4" onclick="app.showView('view-dashboard')">Volver</button>
            `;
            return;
        }

        let config = {};
        if (type === 'social') config = { title: "Foto en Redes", pts: 50, icon: "ph-instagram-logo", text: "Toma una foto en el evento y compártela. Luego valida aquí para ganar puntos." };
        if (type === 'colleague') config = { title: "Foto con Colega", pts: 50, icon: "ph-users", text: "Tómate una foto con ese colega que no veías hace tiempo." };
        if (type === 'card') config = { title: "Tarjeta Presentación", pts: 50, icon: "ph-address-book", text: "Toma foto a la tarjeta de un expositor para guardar su contacto." };

        if (type === 'survey') {
            titleEl.textContent = "Encuesta";
            contentEl.innerHTML = `
                <div class="survey-section">
                    <p>A. Salón de exposiciones y conferencias</p>
                    <div class="stars" id="stars-A">
                        <i class="ph-fill ph-star" onclick="app.rate('A',1)"></i><i class="ph-fill ph-star" onclick="app.rate('A',2)"></i><i class="ph-fill ph-star" onclick="app.rate('A',3)"></i><i class="ph-fill ph-star" onclick="app.rate('A',4)"></i><i class="ph-fill ph-star" onclick="app.rate('A',5)"></i>
                    </div>
                </div>
                <div class="survey-section">
                    <p>B. Evaluación de las charlas</p>
                    <div class="stars" id="stars-B">
                        <i class="ph-fill ph-star" onclick="app.rate('B',1)"></i><i class="ph-fill ph-star" onclick="app.rate('B',2)"></i><i class="ph-fill ph-star" onclick="app.rate('B',3)"></i><i class="ph-fill ph-star" onclick="app.rate('B',4)"></i><i class="ph-fill ph-star" onclick="app.rate('B',5)"></i>
                    </div>
                </div>
                <div class="survey-section">
                    <p>C. Evento en general</p>
                    <div class="stars" id="stars-C">
                        <i class="ph-fill ph-star" onclick="app.rate('C',1)"></i><i class="ph-fill ph-star" onclick="app.rate('C',2)"></i><i class="ph-fill ph-star" onclick="app.rate('C',3)"></i><i class="ph-fill ph-star" onclick="app.rate('C',4)"></i><i class="ph-fill ph-star" onclick="app.rate('C',5)"></i>
                    </div>
                </div>
                <div class="survey-section">
                    <p>D. Opinión</p>
                    <textarea placeholder="Escribe tu opinión aquí..."></textarea>
                </div>
                <button class="btn btn-primary mt-4" onclick="app.completeExtra('survey', 100)">Enviar Encuesta (+100 pts)</button>
            `;
            return;
